CREATE TABLE "PaperAccount" ("userId" TEXT PRIMARY KEY, "initialCash" DOUBLE PRECISION NOT NULL DEFAULT 100000, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PaperWallet" ("userId" TEXT NOT NULL, "asset" TEXT NOT NULL, "available" DOUBLE PRECISION NOT NULL DEFAULT 0, "locked" DOUBLE PRECISION NOT NULL DEFAULT 0, "averageCost" DOUBLE PRECISION NOT NULL DEFAULT 0, "realizedPnl" DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY ("userId", "asset"));
CREATE TABLE "PaperOrder" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "market" TEXT NOT NULL, "side" TEXT NOT NULL, "type" TEXT NOT NULL, "price" DOUBLE PRECISION NOT NULL, "qty" DOUBLE PRECISION NOT NULL, "filledQty" DOUBLE PRECISION NOT NULL DEFAULT 0, "averagePrice" DOUBLE PRECISION NOT NULL DEFAULT 0, "fees" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'OPEN', "lastQuoteId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PaperFill" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "originalOrderId" TEXT NOT NULL, "market" TEXT NOT NULL, "side" TEXT NOT NULL, "type" TEXT NOT NULL, "price" DOUBLE PRECISION NOT NULL, "qty" DOUBLE PRECISION NOT NULL, "fee" DOUBLE PRECISION NOT NULL, "realizedPnl" DOUBLE PRECISION NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PaperOrder_status_market_idx" ON "PaperOrder"("status", "market");
CREATE INDEX "PaperOrder_userId_createdAt_idx" ON "PaperOrder"("userId", "createdAt");
CREATE INDEX "PaperFill_userId_createdAt_idx" ON "PaperFill"("userId", "createdAt");
